// Read-only built-in texture images shipped in server/builtin-materials/ (Phase 17.1): `<imageId>.png` and its
// thumbnail `<imageId>.thumb.webp`, generated by `npm run materials:build`. Only IDs in the shared catalog
// (shared/domain/house/builtinMaterials.ts) resolve; nothing here writes.
import { createHash } from "node:crypto";
import { readFile } from "node:fs/promises";
import { join, resolve } from "node:path";
import { fileURLToPath } from "node:url";
import { findBuiltInImage } from "../../shared/domain/house/builtinMaterials";
import { isErrnoCode } from "../lib/json";

export const defaultBuiltinMaterialsDir = resolve(
  fileURLToPath(new URL(".", import.meta.url)),
  "../builtin-materials",
);

export type BuiltinImageFile = Readonly<{ bytes: Buffer; mediaType: string; etag: string }>;

export class BuiltinImageRepository {
  constructor(private readonly root: string = defaultBuiltinMaterialsDir) {}

  /** The file name of a built-in image or its thumbnail; undefined for an unknown ID. */
  fileName(imageId: string, which: "file" | "thumbnail"): string | undefined {
    const image = findBuiltInImage(imageId);
    if (image === undefined) return undefined;
    return which === "file" ? image.file : `${image.id}.thumb.webp`;
  }

  /** Bytes, media type and a content hash (ETag) of a built-in image; undefined when unknown or missing. */
  async read(imageId: string, which: "file" | "thumbnail"): Promise<BuiltinImageFile | undefined> {
    const name = this.fileName(imageId, which);
    if (name === undefined) return undefined;
    let bytes: Buffer;
    try {
      bytes = await readFile(join(this.root, name));
    } catch (error: unknown) {
      if (isErrnoCode(error, "ENOENT")) return undefined;
      throw error;
    }
    return {
      bytes,
      mediaType: which === "file" ? "image/png" : "image/webp",
      etag: `"${createHash("sha256").update(bytes).digest("hex").slice(0, 32)}"`,
    };
  }
}
